#define PI 3.14159265359

vec2 rotate(vec2 v, float a) {
    float s = sin(a);
    float c = cos(a);
    mat2 m = mat2(c, s, -s, c);
    return m * v;
}

float GridScl = 12.0;
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize pixel coordinates to range from -1 to 1
    vec2 uv = ( 2.*fragCoord - iResolution.xy ) / iResolution.y;
    //uv*=mat2(2,1,-2,1);
    // Grid setup
    uv *= GridScl; // Scale up UVs for a grid
    uv.x +=.5;
    vec2 gridID = floor(uv); // Integer grid cell position
    vec2 gridCenter = gridID + 0.5; // Center of the current grid cell
    // Calculate local UV within the grid cell
    vec2 localUV = fract(uv) - 0.5;

    // Mouse position normalized to the same coordinate space
    vec2 mouse = iMouse.xy / iResolution.xy * 2.0 - 1.0;
    mouse.x *= iResolution.x / iResolution.y; // Correct aspect ratio
    // Default circular position center if mouse not clicked
    if (iMouse.z <= 0.) mouse = vec2(0);
    // Find the grid ID of the mouse
    vec2 mouseGridID = floor(mouse * GridScl);
    // Determine rotation direction based on proximity to mouse grid
    float rotationDirection = dot(gridID, mouseGridID) > 0.0 ? 1.0 : -1.0;

    ///////////////////////////
    // Buffer: Velocity and Position suggested by @elenzil
    vec2 velocity = vec2(0.0); // Start with zero velocity
    vec2 homeOrientation = vec2(1.0, 0.0); // Default home orientation (right direction)

    // Calculate influence of mouse on velocity
    vec2 mouseDir = normalize(mouse - gridCenter / GridScl);
    float mouseDist = length(mouse - gridCenter / GridScl);
    float mouseInfluence = 1.0 - smoothstep(0.0, 0.5, mouseDist);

    velocity += mouseDir * mouseInfluence; // Add mouse influence to velocity

    // Mix velocity with a tendency to return to home orientation
    vec2 orbitalPos = mix(homeOrientation, velocity, 0.5);
    orbitalPos = normalize(orbitalPos); // Normalize to prevent drift
    float t = (iTime*.75)*(PI*2.);
    // Rotate local UV based on orbital position
    float rotationAngle = atan(orbitalPos.y, orbitalPos.x);
    vec2 rotatedUV1 = rotate(localUV, t * rotationAngle);
    vec2 rotatedUV2 = rotate(localUV, t * -rotationAngle);

    // Rotation speed inversely proportional to distance from the mouse grid
    float rotationSpeed = mix(0.0, 5.0, smoothstep(0.0, 1.0, 1.0 - mouseDist));

    // Circle parameters
    float radius1 = 0.4;
    // thickness with AA - Thanks @fabriceNeyret2
    float thickness1 = 6.*3./iResolution.y;

    float radius2 = 0.125;
    // thickness with AA - Thanks @fabriceNeyret2
    float thickness2 = 6.*3./iResolution.y;

    // Calculate distances and strokes for the circles
    float dist1 = length(rotatedUV1);
    float stroke1 = smoothstep(radius1 + thickness1, radius1, dist1)
                  - smoothstep(radius1, radius1 - thickness1, dist1);
    float dist2 = length(rotatedUV2 - vec2(0.25));

    vec2 rotatedUV3 = rotate(localUV, (-t*.125) * rotationSpeed * rotationDirection);
    float dist3 = length(rotatedUV3 + vec2(0.25));
    float stroke2 = smoothstep(radius2 + thickness2, radius2, dist2); 
    vec3 stroke3 = vec3(smoothstep(radius2 + thickness2, radius2, dist3));

    vec3 lightDir = normalize(vec3(1.0, 1.0, 2.0)); // Light coming from the top-right
    vec3 normal = normalize(vec3(rotatedUV3, sqrt(radius2 * radius2 - dist3 * dist3))); // Sphere normal
    float lightIntensity = max(dot(normal, lightDir), 0.0); // Diffuse lighting
    // Shaded color
    vec3 baseColor = vec3(0.2, 0.5, 0.8); // Base color for the sphere
    vec3 shadedColor = baseColor * lightIntensity;
    stroke3*=shadedColor;
    vec3 color = vec3(stroke2 + stroke1*mouseDist, stroke2 + stroke2*mouseDist, stroke1/mouseDist - stroke2)+vec3(stroke3);

    fragColor = vec4(color, 1.0); // Set the final color 
}
